/* English build of inventory.js — generated by cli/i18n.php, do not edit */
/* ==========================================================================
   Inventory: نوافذ Movements وتغيير حالة Devices
   ========================================================================== */
(function (document) {
  'use strict';

  var UNIT_ACTIONS = { install: 'Install unit', 'return': 'Return to warehouse', faulty: 'Record damage', lost: 'Record loss' };

  function toggle(scope, type) {
    scope.querySelectorAll('[data-show]').forEach(function (el) {
      var show = el.getAttribute('data-show').split(',').indexOf(type) !== -1;
      el.hidden = !show;
      el.querySelectorAll('input, select, textarea').forEach(function (i) { i.disabled = !show; });
    });
  }

  // ---------------------------------------------------------------- Movements
  var move = document.getElementById('inv-move');
  if (move) {
    var form = move.querySelector('[data-inv-move]');
    var serialMode = false;
    var unitLabel = '';

    var apply = function () {
      var checked = form.querySelector('input[name=type]:checked');
      var type = serialMode ? 'in' : (checked ? checked.value : 'in');
      move.querySelectorAll('[data-mode]').forEach(function (el) {
        var on = el.getAttribute('data-mode') === (serialMode ? 'serial' : 'qty');
        el.hidden = !on;
        el.querySelectorAll('input, select, textarea').forEach(function (i) { i.disabled = !on; });
      });
      toggle(form, type);
      var notes = form.querySelector('[data-wide-when]');
      if (notes) {
        var wide = notes.getAttribute('data-wide-when').split(',').indexOf(type) !== -1;
        notes.classList.toggle('col-12', wide);
        notes.classList.toggle('col-6', !wide);
      }
      var lbl = form.querySelector('[data-qty-label]');
      if (lbl) { lbl.textContent = type === 'adjust' ? 'Actual balance after stocktake' : 'Quantity'; }
    };

    form.addEventListener('change', function (e) { if (e.target.name === 'type') { apply(); } });

    move.addEventListener('modal:open', function (e) {
      var t = e.detail && e.detail.trigger;
      if (!t) { return; }
      form.reset();
      form.action = t.getAttribute('data-url');
      serialMode = t.getAttribute('data-serial') === '1';
      unitLabel = t.getAttribute('data-unit') || '';
      move.querySelector('[data-inv-name]').textContent = t.getAttribute('data-name') || '';
      move.querySelector('[data-inv-balance]').textContent = 'Balance: ' + (t.getAttribute('data-balance') || '0') + ' ' + unitLabel;
      move.querySelector('[data-inv-unit]').textContent = unitLabel;
      var type = t.getAttribute('data-type') || 'in';
      var radio = form.querySelector('input[name=type][value="' + type + '"]');
      if (radio) { radio.checked = true; }
      var cost = t.getAttribute('data-cost');
      if (cost) { form.querySelector('[name=unit_cost]').value = cost; }
      move.querySelector('[data-inv-title]').textContent = serialMode ? 'Add units' : 'Stock movement';
      apply();
      setTimeout(function () {
        var f = form.querySelector(serialMode ? '[name=serials]' : '[name=qty]');
        if (f) { f.focus(); }
      }, 40);
    });
  }

  // ---------------------------------------------------------------- نموذج Item
  document.querySelectorAll('[data-item-fields]').forEach(function (box) {
    var cb = box.querySelector('[data-track-serial]');
    var unitSel = box.querySelector('[data-unit-select]');
    if (!cb || !unitSel) { return; }
    var sync = function () {
      var qty = box.querySelector('[data-opening="qty"]');
      var ser = box.querySelector('[data-opening="serial"]');
      if (qty) { qty.hidden = cb.checked; }
      if (ser) { ser.hidden = !cb.checked; }
    };
    cb.addEventListener('change', function () { if (cb.checked) { unitSel.value = 'piece'; } sync(); });
    unitSel.addEventListener('change', function () { if (unitSel.value !== 'piece') { cb.checked = false; } sync(); });
    sync();
  });

  // ---------------------------------------------------------------- Devices
  var unit = document.getElementById('inv-unit');
  if (unit) {
    var uform = unit.querySelector('[data-inv-unit]');
    unit.addEventListener('modal:open', function (e) {
      var t = e.detail && e.detail.trigger;
      if (!t) { return; }
      uform.reset();
      var action = t.getAttribute('data-action');
      uform.action = t.getAttribute('data-url');
      uform.querySelector('[name=action]').value = action;
      unit.querySelector('[data-unit-title]').textContent = UNIT_ACTIONS[action] || '';
      unit.querySelector('[data-unit-serial]').textContent = t.getAttribute('data-serial') || '';
      unit.querySelector('[data-unit-item]').textContent = t.getAttribute('data-item') || '';
      var btn = unit.querySelector('[data-unit-submit]');
      btn.classList.toggle('btn-danger', action === 'faulty' || action === 'lost');
      btn.classList.toggle('btn-primary', !(action === 'faulty' || action === 'lost'));
      toggle(uform, action);
    });
  }
})(document);
